package ch.local.autoscroll;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.widget.*;import android.view.*;
public class MainActivity extends Activity {
 LinearLayout l; SharedPreferences p; TextView diagnostic; final Handler handler=new Handler(Looper.getMainLooper()); final Runnable refresh=new Runnable(){public void run(){if(diagnostic!=null)diagnostic.setText("Service: "+(ScrollService.connected?"connected":"not connected")+"\nLast window: "+ScrollService.lastPackage+"\nRicardo detected: "+ScrollService.detected+"\nOverlay: "+ScrollService.overlayState+"\nLast Ricardo: "+ScrollService.lastRicardo+"\nGesture: "+ScrollService.gestureState+"\n\nRecent events (local):\n"+android.text.TextUtils.join("\n",ScrollService.history));handler.postDelayed(this,500);}}; @Override protected void onResume(){super.onResume();handler.post(refresh);} @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
 void showLab(){ScrollView sc=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);sc.addView(rows);for(int i=1;i<=80;i++){TextView row=new TextView(this);row.setText("Ligne de test "+i);row.setTextSize(24);row.setPadding(24,32,24,32);rows.addView(row);}android.app.Dialog d=new android.app.Dialog(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Button go=new Button(this);go.setText("Tester un glissement");root.addView(go);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));d.setContentView(root);d.show();d.getWindow().setLayout(-1,-1);go.setOnClickListener(v->{int[] xy=new int[2];sc.getLocationOnScreen(xy);int before=sc.getScrollY();go.setEnabled(false);ScrollService.testSwipe(xy[0]+sc.getWidth()/2f,xy[1]+sc.getHeight()*.75f,xy[1]+sc.getHeight()*.25f);handler.postDelayed(()->{go.setText("Déplacement : "+(sc.getScrollY()-before)+" px");go.setEnabled(true);},1800);});} void choice(String label,String key,String[] vals,int def){TextView t=new TextView(this);t.setText(label);l.addView(t);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,vals));s.setSelection(p.getInt(key,def));l.addView(s);s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){} public void onItemSelected(AdapterView<?> a,View v,int i,long id){p.edit().putInt(key,i).apply();}});}
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("cfg",0);ScrollView sc=new ScrollView(this);l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,32,32,32);sc.addView(l);setContentView(sc);sc.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(a.left,a.top,a.right,a.bottom);}return i;});TextView title=new TextView(this);title.setText("Ricardo AutoScroll v2.4");title.setTextSize(26);l.addView(title);diagnostic=new TextView(this);l.addView(diagnostic);Button test=new Button(this);test.setText("Test floating controls (no gestures)");test.setOnClickListener(v->ScrollService.testOverlay());l.addView(test);Button lab=new Button(this);lab.setText("Test défilement interne");lab.setOnClickListener(v->showLab());l.addView(lab);choice("Mode","mode",new String[]{"Étapes","Continu"},0);choice("Durée (s)","duration",new String[]{"30","60","90","120","180"},2);choice("Glissement (ms)","speed",new String[]{"600","800","1000","1500"},1);choice("Pause (s)","pause",new String[]{"1.5","2.5","4","6"},1);choice("Chevauchement cible (%)","overlap",new String[]{"15","20","25"},1);choice("Compte à rebours (s)","count",new String[]{"3","5","10"},1);TextView info=new TextView(this);info.setText("Active le service, ouvre les résultats Ricardo, lance l'enregistreur Samsung puis touche Start.");l.addView(info);Button btn=new Button(this);btn.setText("Paramètres d’accessibilité");btn.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));l.addView(btn);}
}